function sanitizeDiagnostic(value: string): string {
  let safe = value.split(String.fromCharCode(27)).map((part) =>
    part.replace(/^\[[0-9;]*m/, "")
  ).join("");
  for (
    const name of [
      "FNOX_AGE_KEY",
      "FNOX_AGE_KEY_AGENT",
      "GITHUB_TOKEN",
