    if (secret) safe = safe.replaceAll(secret, "[redacted]");
  }
  return safe.replace(
    /[a-z][a-z0-9+.-]*:\/\/[^\s"'<>]+/gi,
    (url) => repositoryLabel(url) ?? "[redacted URL]",
