      while !@fs.exists(directory + "/up-waiting") || !@fs.read_file(directory + "/progress-stderr").text().contains("creating machine") { @async.sleep(10) }
    })
    assert_eq(child.try_wait(), None)
    assert_eq(@fs.read_file(directory + "/progress-stdout").text(), "")
